def kernel(self, A: ndarray):
    # --- optimized implementation ---
    N = self.N
    for i in range(N):
        # handle sub-diagonal entries
        if i > 0:
            row = A[i, :i]                          # A[i,0:i]
            for j in range(1, i):
                col = A[:i, j]                     # A[0:i,j]
                A[i, j] -= row @ col
                A[i, j] /= A[j, j]

        # handle super-diagonal entries in a vectorized way
        if i < N:
            if i > 0:
                row = A[i, :i]
                cols = A[:i, i:]                   # A[0:i, i:N]
                A[i, i:] -= row @ cols
            else:
                # i == 0: nothing to subtract
