                w -= np.dot( A[i,0:j], A[0:j,j] )
                A[i, j] = w / A[j, j]

            for j in range(i, self.N):
                w = A[i, j]
                w -= np.dot( A[i,0:i], A[0:i,j] )
                A[i, j] = w

        w = b[0:self.N]
        for i in range(0, self.N):
            w[i] -= np.dot( A[i,0:i], y[0:i] )
            y[i] = w[i]

        for i in range(self.N - 1, -1, -1):
            w = y[i]
            w -= np.dot( A[i,i+1:self.N], x[i+1:self.N] )
            x[i] = w / A[i, i]

